-- Candidato para pruebas locales, NO aplicar en producción antes de pruebas RLS.
-- Refuerza integridad entre hogares y añade operaciones transaccionales de membresía.
alter table public.plans add constraint plans_household_id_id_unique unique(household_id,id);
alter table public.usage_logs drop constraint usage_logs_plan_id_fkey;
alter table public.usage_logs add constraint usage_plan_same_household foreign key (household_id,plan_id) references public.plans(household_id,id);
create unique index notification_preferences_user_household on public.notification_preferences(household_id,user_id);
create table public.household_invitations(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,email text not null,token_hash bytea not null unique,expires_at timestamptz not null,accepted_at timestamptz,created_by uuid not null references auth.users(id));
alter table public.household_invitations enable row level security;
-- No direct policies: tokens and privileged writes are exposed only by validated functions.
create function public.is_household_owner(target uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.household_memberships where household_id=target and user_id=auth.uid() and role='owner' and active) $$;
revoke all on function public.is_household_owner(uuid) from public; grant execute on function public.is_household_owner(uuid) to authenticated;
create function public.create_household(household_name text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare new_id uuid; begin if auth.uid() is null or length(trim(household_name)) not between 1 and 80 then raise exception 'invalid request'; end if; insert into public.households(name,owner_id) values(trim(household_name),auth.uid()) returning id into new_id; insert into public.household_memberships(household_id,user_id,role) values(new_id,auth.uid(),'owner'); return new_id; end $$;
revoke all on function public.create_household(text) from public; grant execute on function public.create_household(text) to authenticated;
create function public.create_household_invitation(target uuid, invited_email text) returns text language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare token text; begin if not public.is_household_owner(target) or length(trim(invited_email)) not between 3 and 254 or position('@' in invited_email)=0 then raise exception 'invalid request';end if;token:=encode(gen_random_bytes(32),'hex');insert into public.household_invitations(household_id,email,token_hash,expires_at,created_by) values(target,lower(trim(invited_email)),digest(token,'sha256'),now()+interval '24 hours',auth.uid());return token;end $$;
revoke all on function public.create_household_invitation(uuid,text) from public; grant execute on function public.create_household_invitation(uuid,text) to authenticated;
create function public.accept_household_invitation(token text) returns uuid language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare inv public.household_invitations%rowtype; user_email text; begin if auth.uid() is null or length(token)<>64 then raise exception 'invalid invitation'; end if;select email into user_email from auth.users where id=auth.uid() and email_confirmed_at is not null;select * into inv from public.household_invitations where token_hash=digest(token,'sha256') and accepted_at is null and expires_at>now() for update;if not found or lower(user_email) is distinct from inv.email then raise exception 'invalid invitation';end if;insert into public.household_memberships(household_id,user_id,role,active) values(inv.household_id,auth.uid(),'member',true) on conflict(household_id,user_id) do update set active=true;update public.household_invitations set accepted_at=now() where id=inv.id;return inv.household_id;end $$;
revoke all on function public.accept_household_invitation(text) from public; grant execute on function public.accept_household_invitation(text) to authenticated;
create function public.revoke_household_member(target uuid,member_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.is_household_owner(target) or member_id=auth.uid() then raise exception 'invalid request';end if;update public.household_memberships set active=false where household_id=target and user_id=member_id and role='member';update public.notification_deliveries set state='cancelled' where user_id=member_id and state in ('pending','retry') and event_id in (select id from public.notification_events where household_id=target);end $$;
revoke all on function public.revoke_household_member(uuid,uuid) from public; grant execute on function public.revoke_household_member(uuid,uuid) to authenticated;
create policy plans_update on public.plans for update to authenticated using(public.is_household_member(household_id)) with check(public.is_household_member(household_id));
create policy usage_update on public.usage_logs for update to authenticated using(public.is_household_member(household_id)) with check(public.is_household_member(household_id));
create table public.pvpc_days(id uuid primary key default gen_random_uuid(),date_local date not null,source text not null,revision text,validated_at timestamptz not null default now(),unique(date_local,source));
create table public.pvpc_intervals(day_id uuid not null references public.pvpc_days(id) on delete cascade,start_utc timestamptz not null,end_utc timestamptz not null,price_eur_kwh numeric not null,primary key(day_id,start_utc),check(end_utc>start_utc));
alter table public.pvpc_days enable row level security;alter table public.pvpc_intervals enable row level security;
create policy price_days_read on public.pvpc_days for select to anon,authenticated using(true);create policy price_intervals_read on public.pvpc_intervals for select to anon,authenticated using(true);
create table public.notification_events(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.households(id) on delete cascade,event_key text not null unique,kind text not null,scheduled_at timestamptz not null,expires_at timestamptz not null,payload jsonb not null default '{}'::jsonb);
alter table public.notification_events enable row level security;
alter table public.notification_deliveries add column event_id uuid references public.notification_events(id) on delete cascade,add column attempt_count integer not null default 0,add column next_retry_at timestamptz,add column lease_until timestamptz,add column last_error_code text;
-- Queue and channels intentionally deny direct client access. Server workers require service-only entry points.

